    TE: { short: 'à°¹à±Œà°°à°¾â€“à°¯à°¶à±à°µà°‚à°¤à°ªà±‚à°°à± à°¦à±à°°à°‚à°¤à±‹', full: 'à°¹à±Œà°°à°¾â€“à°¯à°¶à±à°µà°‚à°¤à°ªà±‚à°°à± à°Žà°¸à°¿ à°¦à±à°°à°‚à°¤à±‹ à°Žà°•à±à°¸à±â€Œà°ªà±à°°à±†à°¸à±', fullRoute: 'à°¹à±Œà°°à°¾â€“à°¯à°¶à±à°µà°‚à°¤à°ªà±‚à°°à± à°¦à±à°°à°‚à°¤à±‹: à°¹à±Œà°°à°¾ â†’ à°¯à°¶à±à°µà°‚à°¤à°ªà±‚à°°à±' },
